  tools.mcp__solo__get_process_output({project_id:4,process_id:960,lines:80})
]);
text("WHOAMI\n"); text(me);
text("\nSCRATCHPAD_276\n"); text(scratchpad);
text("\nPROCESS_960_STATUS\n"); text(status);
text("\nPROCESS_960_OUTPUT\n"); text(output);

