  cmd: "sed -n '1,180p' .orbit/quality-gates/quality-check-2026-07-10T014433Z-0340c27d6ab8.json\nsed -n '1,80p' .orbit/quality-gates/docs-lint-2026-07-10T014444Z-bd7245f6e2ec.json",
  workdir: "/Users/nckrtl/orbit/.worktrees/core-injected-output-capability",
  yield_time_ms: 10000,
  max_output_tokens: 12000
});
text(r.output);

