  tools.exec_command({
    cmd: "git show --stat --format=fuller 9ec756c5574db40bcb155a3b20021c5e338f15be",
    workdir: "/Users/nckrtl/orbit/.worktrees/core-injected-output-capability",
    yield_time_ms: 10000,
